import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    if n == 0:
        print("")
        return

    arr = list(map(int, data[1:n+1]))

    result = []
    prefix_sum = 0

    for i in range(n):
        if arr[i] % 2 == 0:
            prefix_sum += arr[i]
            result.append(prefix_sum)
        else:
            prefix_sum = 0
            result.append(arr[i])

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
